Section FXALL.
Context {fx : FPState}.
Section Phase.
  Context {AC : AllocCeiling} {RRND : RunRandom} {AMB : Amb} {UL : ULim}.
  Variable MI : MallocIface SEGS L.
  Variable AINV0 : AS MI -> LibIface.mem -> Model -> Prop.
  Variables (TIGHT FRESH44 : AS MI -> Prop).
  Hypothesis DM : drv_mallocT MI AINV0 TIGHT FRESH44.

  Variable sp0 : word.
  Variables a0s path : list byte.
  Variable envv : list (list byte).
  Variable tid : word.
  Variable rdraw : EntryDraw.
  Variable regs0 : bvmap 5 word.
  Variable mem0 : word -> option byte.
  Variable brk : word.
  Variable mbase : word.
  Variable fs0 : Fs.
  Variable stdin0 : InputStream.
  Variable content : list byte.
  Hypothesis Hva : valid_argv [a0s; path].
  Hypothesis Hve : valid_envp envv.
  Hypothesis Hvsp : valid_sp sp0.
  Hypothesis Htid : (0 < bv_unsigned tid < 2 ^ 22)%Z.
  Hypothesis ME : main_entry sp0 rdraw [a0s; path] envv a_uid a_hwcap tid regs0 mem0.
  Hypothesis Hbrk : valid_brk RSEGS brk.
  Hypothesis Hfile : fs_lookup fs0 path = Some content.
  Hypothesis Hpne : path <> [].
  Hypothesis Hpnd : path <> dot_path.
  Hypothesis Hplen : (length path <= 4095)%nat.

  Hypothesis HAC : (alloc_ceiling = bv_unsigned sp0 - 8388608)%Z.
  Hypothesis HRR : (rr_canary = bv_unsigned (canary rdraw))%Z.
  Hypothesis HRS : (rr_secret = rr_secret_of (ed_random rdraw))%Z.

  Let SPlo : (0x7fff80000000 <= bv_unsigned sp0)%Z := proj1 Hvsp.
  Let SPhi : (bv_unsigned sp0 <= 0x800000000000)%Z := proj1 (proj2 Hvsp).
  Let SPal : (bv_unsigned sp0 mod 16 = 0)%Z := proj2 (proj2 Hvsp).
  Let L : Z := Z.of_nat (length content).
  #[local] Notation SP0 := (bv_unsigned sp0).
  #[local] Notation TID := (bv_unsigned tid).
  #[local] Notation P1 := (bv_unsigned (p1 sp0 a0s path envv)).
  #[local] Notation model0 := (U1RFront.model0 sp0 a0s path envv tid brk mbase fs0 stdin0).

  Variable KEND : TSet.
  Hypothesis HREF : forall A R M mo, oom_pre MI SP0 TID P1 path fs0 A R M mo ->
    srealizes RSEGS (mkCfg (mkst R (Z_to_bv 64 0x65a84) M (seg_rom RSEGS)) mo) (t_die msg_refused fs0).
  Hypothesis HEND : forall p cap A R M mo, rend MI TIGHT SP0 TID P1 path content fs0 p cap A R M mo ->
    srealizes RSEGS (mkCfg (mkst R (Z_to_bv 64 0x65938) M (seg_rom RSEGS)) mo) KEND.

